import { readFileSync } from 'node:fs';
import { randomInt } from 'node:crypto';

/**
 * What a Diamond / Black Diamond box can pay out - the SERVER's copy of the game's design pools,
 * so the server rolls the design and a client can never name one.
 *
 * `data/designs.json` is GENERATED by Unity (`EditorTools.DesignManifest.Export`) from
 * `DesignDrops.Pool` itself, never hand-edited - so the pools here are the game's pools. Re-export
 * whenever a design is added, then deploy.
 *
 * A Black Diamond WEAPON carries its RELIC (`relic`): the pair is one payout, minted together.
 */
export interface DesignPiece {
  id: string;
  name: string;
  slot: string;
  class?: string;
  /** Black Diamond relics: the locked finisher. */
  signature?: string;
}

export interface DesignEntry extends DesignPiece {
  relic?: DesignPiece;
  /** A Diamond armour SET (slot "Set", id `set_<prefix>`) - ONE design and ONE token owning every
   *  piece listed here (the user's call, 2026-10-13). */
  pieces?: DesignPiece[];
}

export type DyeRarity = 'Common' | 'Uncommon' | 'Rare' | 'VeryRare';

interface Manifest {
  version: number;
  exportedAt: string;
  costs: { random: number; targeted: number };
  tiers: Record<string, DesignEntry[]>;
  /** Every dye colour (DyeCatalog) - ids are permanent. */
  swatches?: { id: string; name: string; rarity: DyeRarity }[];
  /** Every dyeable design and how many dye channels it has (1 main, or main + accent). */
  dyeable?: Record<string, number>;
  /** The rolled portrait poses (PoseCatalog) - ids are permanent. */
  poses?: { id: string; name: string }[];
  /** The HUB THEMES (Hub.HubThemes) a character can earn - each a whole room: floor, wall and every
   *  hub item. Ids are permanent ("hub.study"); the Cloister is everyone's and never listed. */
  themes?: { id: string; name: string }[];
}

let manifest: Manifest | null = null;

export function designs(): Manifest {
  manifest ??= JSON.parse(
    readFileSync(new URL('../data/designs.json', import.meta.url), 'utf8'),
  ) as Manifest;
  return manifest;
}

/**
 * DesignDrops.Pool: the tier's designs, optionally narrowed to a slot and (weapons) a class.
 * Never a RING (the user's call, 2026-10-13: at their size in game rings can hardly be made
 * unique, and they are not to be paid for - every ring is stat-bearing gear that does not trade).
 * Checked here as well as in the game, so a manifest exported before the rule cannot pay one out.
 */
export function pool(tier: string, slot?: string, weaponClass?: string): DesignEntry[] {
  return (designs().tiers[tier] ?? []).filter(
    (d) => d.slot !== 'Ring' &&
      (!slot || d.slot === slot) && (!weaponClass || d.slot !== 'Weapon' || d.class === weaponClass),
  );
}

/** A uniform pick from the server's own randomness. */
export function pick(entries: DesignEntry[]): DesignEntry | null {
  return entries.length === 0 ? null : entries[randomInt(entries.length)];
}
